/* cosmos-route-v3-begin: applied after the upstream bundle */
(() => {
  const Plugin = module.exports.default || module.exports;
  const proto=Plugin.prototype;
  if(proto.__cosmosRouteV3)return;
  proto.__cosmosRouteV3=true;
  const originalLoad=proto.onload, originalMatch=proto.matchAndMoveFile, originalRules=proto.areThereRulesToApply;
  proto.loadCosmosRoute=async function(){
    const base='宇宙/演化/脚本/lib/';
    const schema=JSON.parse(await this.app.vault.adapter.read(base+'system-schema.json'));
    if(schema.version<3)throw Error('路由适配要求属性模型 v3。');
    const mod={exports:{}};
    new Function('module','exports',await this.app.vault.adapter.read(base+'system-engine.cjs'))(mod,mod.exports);
    this.cosmosRoute=mod.exports(this.app,schema);
  };
  proto.areThereRulesToApply=function(){return !!this.cosmosRoute || originalRules.call(this);};
  proto.onload=async function(){
    await this.loadCosmosRoute();
    await originalLoad.call(this);
    if(!this.app.commands.findCommand('auto-mover:AutoMover:move-files')){
      this.addCommand({id:'AutoMover:move-files',name:'按 route 校正文件目录',callback:()=>this.goThroughAllFiles()});
      this.addRibbonIcon('file-input','AutoMover：按 route 校正目录',()=>this.goThroughAllFiles());
    }
    this.registerEvent(this.app.vault.on('rename',(file,oldPath)=>{
      this.cosmosRoute.syncRouteAfterRename(file,oldPath).catch(error=>new (require('obsidian').Notice)('路由同步失败：'+error.message));
    }));
    if(this.settings.cosmosProjectIndexEnabled===true)await this.loadCosmosProjectIndex();
  };
  // An explicit opt-in protects the cancelled feature, including its manual commands.
  proto.loadCosmosProjectIndex=async function(){
    const base='宇宙/演化/脚本/lib/';
    const schema=JSON.parse(await this.app.vault.adapter.read(base+'system-schema.json'));
    const indexModule={exports:{}};
    new Function('module','exports',await this.app.vault.adapter.read(base+'project-index.cjs'))(indexModule,indexModule.exports);
    this.cosmosProjectIndex=indexModule.exports(this.app,schema,this.cosmosRoute);
    const index=this.cosmosProjectIndex;
    index.start();
    const signatures=new Map();
    const signature=file=>JSON.stringify({path:file.path,type:this.cosmosRoute.frontmatter(file).type,project:this.cosmosRoute.frontmatter(file).project});
    for(const file of this.app.vault.getMarkdownFiles())signatures.set(file.path,signature(file));
    const schedule=()=>index.schedule(error=>new (require('obsidian').Notice)('项目关联清单同步失败：'+error.message));
    this.registerEvent(this.app.metadataCache.on('changed',file=>{
      if(file.extension!=='md')return;
      const next=signature(file);
      if(signatures.get(file.path)===next)return;
      signatures.set(file.path,next);schedule();
    }));
    this.registerEvent(this.app.metadataCache.on('resolved',schedule));
    this.registerEvent(this.app.vault.on('delete',file=>{
      if(file.extension!=='md')return;
      signatures.delete(file.path);schedule();
    }));
    this.addCommand({id:'sync-project-links',name:'重建项目关联笔记清单',callback:async()=>{
      const result=await index.sync();
      new (require('obsidian').Notice)(`项目清单：更新 ${result.changed||0}，关联 ${result.linked||0}，问题 ${result.issues?.length||0}${result.pending?.length?'，等待笔记索引':''}。`);
      if(result.issues?.length)console.warn('项目关联清单检查',result.issues);
    }});
    this.addCommand({id:'inspect-project-links',name:'检查项目关联',callback:()=>{
      const {issues}=index.collect();
      new (require('obsidian').Notice)(issues.length?issues.map(i=>i.path+'：'+i.reason).join('\n'):'项目关联属性检查通过。',issues.length?12000:4000);
    }});
    this.register(()=>index.stop());
    this.app.workspace.onLayoutReady(schedule);
    this.registerEvent(this.app.vault.on('rename',(file,oldPath)=>{
      if(file.extension==='md'){signatures.delete(oldPath);schedule();}
    }));
  };
  proto.matchAndMoveFile=async function(file){
    if(/^(星云|太阳|月亮|地球|黑洞)\//.test(file.path)){
      const result=await this.cosmosRoute.moveByRoute(file);
      if(result.moved)return 'moved';
      if(result.reason?.includes('同名'))return 'duplicate';
      if(result.unchanged || result.reason?.includes('业务范围'))return null;
      return 'invalid_path';
    }
    return originalMatch.call(this,file);
  };
  proto.goThroughAllFiles=async function(options={}){
    if(this.cosmosBatchRunning)return;
    this.cosmosBatchRunning=true;
    const counts={moved:0,duplicate:0,invalid_path:0,error:0};
    try{
      for(const file of this.app.vault.getFiles()){
        if(!file || this.isFileExcluded(file))continue;
        try{const result=await this.matchAndMoveFile(file);if(result in counts)counts[result]++;}
        catch{counts.error++;}
      }
      if(!options.silentIfUnchanged || counts.moved)new (require('obsidian').Notice)(`目录校正：移动 ${counts.moved}，同名跳过 ${counts.duplicate}，目标不合法 ${counts.invalid_path}，失败 ${counts.error}。`);
      return counts;
    }finally{this.cosmosBatchRunning=false;}
  };
})();
